                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N:
                        dp[i][j][step] = min(dp[i][j][step], dp[ni][nj][step - 1] + grid[i][j])

    min_val = float('inf')
    min_path = []
    for i in range(N):
        for j in range(N):
            if dp[i][j][k] < min_val:
                min_val = dp[i][j][k]
                min_path = [grid[i][j]]
